package routing

// costClassRank maps cost class to numeric rank (lower = cheaper).
var costClassRank = map[string]int{
	"local":        0,
	"cheap":        1,
	"medium":       2,
	"expensive":    3,
	"experimental": -1,
	"":             2, // unknown = medium
}

const StickyAffinityBonus = 250.0
const unknownUtilizationPenalty = 5.0
const unknownPerformancePenalty = 5.0

// scorePolicy returns a score for a candidate under the named policy.
// Higher is better.
//
// Routing priority policy (ported from DDx routing.go):
//   - cheap: local + low-cost preferred; subscription-within-quota next.
//   - default: balanced; light local/subscription preference to avoid spend.
//   - smart: quality first; cloud capability wins; no local bonus.
//
// The policy is policy-aware AND provider-aware via providerBias hooks
// supplied by the caller (cooldown demotion, observation perf bias,
// provider-affinity bias).
func scorePolicy(policy string, cand candidateInternal) float64 {
	total := 0.0
	for _, component := range scoreComponents(policy, cand) {
		total += component
	}
	return total
}

func scoreComponents(policy string, cand candidateInternal) map[string]float64 {
	components := map[string]float64{
		"base":                100,
		"cost":                0,
		"deployment_locality": 0,
		"quota_health":        0,
		"utilization":         0,
		"performance":         0,
		"power":               0,
		"context_headroom":    0,
		"sticky_affinity":     0,
	}
	base := 100.0
	cr := costClassRank[cand.CostClass]
	withinQuota := cand.IsSubscription && cand.QuotaOK
	hasPowerBounds := cand.MinPower > 0 || cand.MaxPower > 0
	add := func(name string, value float64) {
		if value == 0 {
			return
		}
		components[name] += value
	}

	if !hasPowerBounds {
		switch policy {
		case "cheap":
			if cand.CostClass == "local" {
				base += 40
				add("deployment_locality", 40)
			} else if withinQuota {
				base += 20
				add("quota_health", 20)
			}
			base -= float64(cr) * 30
			add("cost", -float64(cr)*30)

		case "default":
			if cand.CostClass == "local" {
				base += 25
				add("deployment_locality", 25)
			} else if withinQuota {
				base += 15
				add("quota_health", 15)
			}
			base -= float64(cr) * 10
			add("cost", -float64(cr)*10)

		case "smart":
			// Quality first; higher cost rank approximates higher capability.
			base += float64(cr) * 20
			add("cost", float64(cr)*20)
			if withinQuota {
				base += 5
				add("quota_health", 5)
			}

		default:
			// Treat unspecified as default.
			if cand.CostClass == "local" {
				base += 25
				add("deployment_locality", 25)
			} else if withinQuota {
				base += 15
				add("quota_health", 15)
			}
			base -= float64(cr) * 10
			add("cost", -float64(cr)*10)
		}
	}

	// Provider preference bias.
	if !hasPowerBounds {
		switch cand.ProviderPreference {
		case "local-first", "":
			if cand.CostClass == "local" {
				base += 30
				add("deployment_locality", 30)
			}
		case "subscription-first":
			if cand.IsSubscription && cand.QuotaOK {
				base += 30
				add("quota_health", 30)
			}
		}
	}

	// Quota signals.
	if cand.IsSubscription {
		// Stale quota penalty.
		if cand.QuotaStale {
			base -= 15
			add("quota_health", -15)
		}

		// Trend-based adjustments.
		switch cand.QuotaTrend {
		case "exhausting":
			base -= 40
			add("quota_health", -40)
		case "burning":
			base -= 20
			add("quota_health", -20)
		case "healthy":
			base += 10
			add("quota_health", 10)
		}

		// Continuous quota pressure: subscription harnesses should start
		// yielding before they are nearly exhausted, with steeper demotion
		// once headroom drops below 50% and again below 20%.
		if cand.QuotaPercentUsed > 0 {
			penalty := quotaPressurePenalty(cand.QuotaPercentUsed)
			base -= penalty
			add("quota_health", -penalty)
		}
	}

	// Historical success-rate adjustment (only when sufficient samples).
	if cand.HistoricalSuccessRate >= 0 {
		switch {
		case cand.HistoricalSuccessRate >= 0.8:
			base += 20
			add("quota_health", 20)
		case cand.HistoricalSuccessRate < 0.5:
			base -= 30
			add("quota_health", -30)
		}
	}
	if cand.ProviderSuccessRate >= 0 {
		switch {
		case cand.ProviderSuccessRate >= 0.8:
			base += 25
			add("quota_health", 25)
		case cand.ProviderSuccessRate < 0.5:
			base -= 35
			add("quota_health", -35)
		}
	}

	// Cooldown demotion: candidate has had recent failures.
	if cand.InCooldown {
		base -= 50
		add("quota_health", -50)
	}

	// Sticky affinity is a bonus after eligibility, not a hard pin.
	if cand.StickyMatch {
		base += StickyAffinityBonus
		add("sticky_affinity", StickyAffinityBonus)
	}

	// Utilization pressure can outweigh stickiness when the chosen server is
	// already busy or saturated.
	// Unknown or stale utilization is treated explicitly. Missing data gets a
	// small penalty so it cannot outrank a peer with real healthy evidence by
	// accident.
	if cand.EndpointSaturated {
		base -= 300
		add("utilization", -300)
	}
	if cand.EndpointLoad > 0 {
		loadPenalty := cand.EndpointLoad * 10
		if cand.EndpointLoadFresh {
			loadPenalty *= 2
		} else {
			loadPenalty += unknownUtilizationPenalty
		}
		if loadPenalty > 60 {
			loadPenalty = 60
		}
		base -= loadPenalty
		add("utilization", -loadPenalty)
	} else if !cand.EndpointLoadFresh {
		base -= unknownUtilizationPenalty
		add("utilization", -unknownUtilizationPenalty)
	}

	// Provider affinity: explicit provider pins are filtered before scoring;
	// this bonus only affects the ordering among still-eligible candidates
	// that share the pinned provider identity.
	if cand.ProviderAffinityMatch {
		base += 15
		add("deployment_locality", 15)
	}

	if cand.Power > 0 && cand.MinPower == 0 && cand.MaxPower == 0 {
		base += float64(cand.Power) * 12
		add("power", float64(cand.Power)*12)
	}
	if cand.Power > 0 {
		if cand.MinPower > 0 && cand.Power < cand.MinPower {
			penalty := float64(cand.MinPower-cand.Power) * 5
			base -= penalty
			add("power", -penalty)
		}
		if cand.MaxPower > 0 && cand.Power > cand.MaxPower {
			penalty := float64(cand.Power - cand.MaxPower)
			base -= penalty
			add("power", -penalty)
		}
	}
	if cand.Power > 0 && cand.CostUSDPer1kTokens > 0 {
		costPenalty := cand.CostUSDPer1kTokens * 500
		if costPenalty > 60 {
			costPenalty = 60
		}
		base -= costPenalty
		add("cost", -costPenalty)
	}
	if cand.Power > 0 && cand.CostUSDPer1kTokens == 0 {
		switch {
		case cand.CostClass == "local":
			base += 15
			add("cost", 15)
		case cand.IsSubscription && cand.QuotaOK && !cand.QuotaStale && cand.QuotaPercentUsed < 80:
			base += 15
			add("quota_health", 15)
		}
	}
	if cand.Power >= 9 && cand.IsSubscription && cand.QuotaOK && !cand.QuotaStale && cand.QuotaPercentUsed < 80 {
		base += 20
		add("power", 20)
	}

	// Context headroom is a ranking signal for otherwise eligible candidates.
	// A larger spare window gives the model more room for completion and tool
	// overhead, so reward it modestly without overpowering the primary policy.
	if cand.ContextHeadroom > 0 {
		headroomBonus := float64(cand.ContextHeadroom) / 1000.0
		if headroomBonus > 30 {
			headroomBonus = 30
		}
		base += headroomBonus
		add("context_headroom", headroomBonus)
	}

	// Observation-derived perf bias.
	havePerfSignal := false
	if cand.ObservedTokensPerSec > 0 {
		// Small additive bonus, scaled.
		bonus := cand.ObservedTokensPerSec / 100.0
		base += bonus
		add("performance", bonus)
		havePerfSignal = true
	}
	if cand.ObservedLatencyMS > 0 {
		// Latency is a tiebreaker-scale signal: faster endpoints gain a small
		// bonus while very slow endpoints receive little benefit.
		bonus := 1000.0 / cand.ObservedLatencyMS
		base += bonus
		add("performance", bonus)
		havePerfSignal = true
	}
	if !havePerfSignal {
		// Missing performance data is deliberate and mildly penalized rather
		// than treated as a hidden zero-value bonus.
		base -= unknownPerformancePenalty
		add("performance", -unknownPerformancePenalty)
	}
	if cand.CostClass == "experimental" {
		base -= 75
		add("deployment_locality", -75)
	}

	// base tracks the implicit profile baseline so the components sum to the
	// same total as scorePolicy's legacy behavior.
	components["base"] = base - (components["cost"] + components["deployment_locality"] + components["quota_health"] + components["sticky_affinity"] + components["utilization"] + components["power"] + components["context_headroom"] + components["performance"])
	return components
}

func quotaPressurePenalty(percentUsed int) float64 {
	if percentUsed <= 0 {
		return 0
	}
	penalty := float64(percentUsed) * 0.5
	if percentUsed > 50 {
		penalty += float64(percentUsed-50) * 1.5
	}
	if percentUsed > 80 {
		penalty += float64(percentUsed-80) * 3
	}
	return penalty
}

package routing

import (
	"fmt"
	"sort"
	"strings"
	"time"

	"github.com/easel/fizeau/internal/modelcatalog"
)

// Request is the routing input. All fields are optional except at least
// one of {Policy, Model, Harness, Provider} should be set (otherwise the
// engine has nothing to disambiguate on).
//
// Provider is present from day one (fixes ddx-8610020e — no soft-preference
// dropping).
type Request struct {
	Policy             string // "cheap" | "default" | "smart" | "air-gapped"
	Model              string // exact concrete model pin
	Provider           string // exact provider pin; constrains routing to one provider identity
	Harness            string // hard preference; constrains routing to one harness
	Reasoning          string // public reasoning scalar
	Permissions        string // "safe" | "supervised" | "unrestricted"
	ProviderPreference string // "local-first" | "subscription-first" | "local-only" | "subscription-only"
	CorrelationID      string // validated sticky route key, when available
	AllowLocal         bool
	Require            []string

	// EstimatedPromptTokens, when > 0, drives context-window gating.
	EstimatedPromptTokens int

	// RequiresTools, when true, requires the candidate to support tool calling.
	RequiresTools bool
	MinPower      int
	MaxPower      int
}

const (
	ProviderPreferenceLocalFirst        = "local-first"
	ProviderPreferenceSubscriptionFirst = "subscription-first"
	ProviderPreferenceLocalOnly         = "local-only"
	ProviderPreferenceSubscriptionOnly  = "subscription-only"

	ContextSourceProviderAPI    = "provider_api"
	ContextSourceProviderConfig = "provider_config"
	ContextSourceCatalog        = "catalog"
	ContextSourceDefault        = "default"
	ContextSourceUnknown        = "unknown"
)

// MinContextWindow returns the minimum context window the request requires,
// derived from EstimatedPromptTokens with a safety margin.
func (r Request) MinContextWindow() int {
	if r.EstimatedPromptTokens <= 0 {
		return 0
	}
	// 1.25x safety margin for response tokens + tool overhead.
	return r.EstimatedPromptTokens + r.EstimatedPromptTokens/4
}

const (
	QuotaTrendUnknown    = "unknown"
	QuotaTrendHealthy    = "healthy"
	QuotaTrendBurning    = "burning"
	QuotaTrendExhausting = "exhausting"
)

// HarnessEntry is the harness-side input the caller (service) supplies.
// It is the routing engine's view of a registered harness; the engine does
// not import the harnesses package directly to keep the dependency narrow.
type HarnessEntry struct {
	Name                string
	Surface             string
	CostClass           string
	IsLocal             bool
	IsSubscription      bool
	IsHTTPProvider      bool
	AutoRoutingEligible bool
	TestOnly            bool
	ExactPinSupport     bool
	DefaultModel        string
	SupportedModels     []string
	SupportedReasoning  []string
	MaxReasoningTokens  int
	SupportedPerms      []string
	SupportsTools       bool

	// Available reflects the harness's discovered availability.
	Available bool

	// QuotaOK / QuotaPercentUsed reflect live quota state (when applicable).
	// SubscriptionOK gates subscription harnesses at the eligibility level:
	// when false, the candidate is ineligible regardless of score.
	QuotaOK          bool
	QuotaPercentUsed int
	QuotaStale       bool
	QuotaTrend       string // unknown|healthy|burning|exhausting
	QuotaReason      string
	SubscriptionOK   bool // false = hard gate; true = score-based demotion

	// InCooldown marks the entire harness as being in a failure cooldown.
	// When true the harness is demoted in score (via candidateInternal.InCooldown)
	// but not hard-rejected, so it can still win when all other harnesses are
	// also unavailable.
	InCooldown bool

	// Providers is the list of providers this harness can dispatch to.
	// For subprocess harnesses (claude/codex) this is typically a single
	// vendor entry. For the native "fiz" harness it is the configured
	// list of HTTP providers.
	Providers []ProviderEntry
}

// ProviderEntry describes one provider available under a harness.
type ProviderEntry struct {
	Name                 string
	BaseURL              string
	ServerInstance       string
	EndpointName         string
	EndpointBaseURL      string
	DefaultModel         string
	Billing              modelcatalog.BillingModel
	CostClass            string
	DiscoveredIDs        []string // models discovered via /v1/models or equivalent
	DiscoveryAttempted   bool
	ContextWindows       map[string]int
	ContextWindowSources map[string]string
	ContextWindow        int
	ContextWindowSource  string
	SupportsTools        bool

	// CostUSDPer1kTokens is the estimated blended USD cost per 1,000 tokens.
	// A zero value with CostSourceUnknown means the provider cost is unknown.
	CostUSDPer1kTokens float64
	// CostSource describes where CostUSDPer1kTokens came from: catalog,
	// subscription, user-config, or unknown.
	CostSource string

	// InCooldown reflects whether this provider is in a failure-cooldown window.
	InCooldown bool

	// ExcludeFromDefaultRouting, when true, prevents this provider from being
	// selected during unpinned automatic routing. An explicit provider, harness,
	// or model pin bypasses this gate so the operator can still reach the
	// provider intentionally. Corresponds to IncludeByDefault=false in config.
	ExcludeFromDefaultRouting bool
}

const (
	// CostSourceCatalog means cost came from the model catalog.
	CostSourceCatalog = "catalog"
	// CostSourceSubscription means cost came from subscription quota pricing.
	CostSourceSubscription = "subscription"
	// CostSourceUnknown means no reliable cost estimate is available.
	CostSourceUnknown = "unknown"
	// CostSourceUserConfig means cost came from explicit user configuration.
	CostSourceUserConfig = "user-config"
)

