// RouteRequest specifies a routing query.
type RouteRequest struct {
	Policy      string // optional named policy bundle: cheap|default|smart|air-gapped
	Model       string
	Provider    string
	Harness     string
	Reasoning   Reasoning
	Permissions string
	AllowLocal  bool
	Require     []string
