215	func scorePowerHintFit(power int, policy RoutePowerPolicy) float64 {
216		if power <= 0 {
217			return 0
218		}
219		if policy.MinPower > 0 && power < policy.MinPower {
220			// Mirror the engine scorer: materially underpowered routes should not
221			// win just because they are cheap.
222			return -float64(policy.MinPower-power) * 12
223		}
224		if policy.MaxPower > 0 && power > policy.MaxPower {
225			return -float64(power - policy.MaxPower)
226		}
227		return 0
228	}
